// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {EtherLotto} from "../src/EtherLotto.sol";

contract InvMutTest is Test {
    EtherLotto c;
    function setUp() public { c = new EtherLotto(); }

    function testFuzz_property(uint64 ts, address actor) public {
        vm.assume(actor != address(0));
        vm.assume(actor.code.length == 0);
        vm.warp(ts);
        // Admissible domain: the on-chain randomness (same formula the contract uses) is 1,
        // i.e. the reference must NOT pay out and must keep the pot intact.
        vm.assume(uint(keccak256(abi.encodePacked(block.timestamp, block.difficulty))) % 2 == 1);

        vm.deal(actor, 10);
        vm.prank(actor);
        c.play{value: 10}();

        // Reference C: random == 1 => no payout, pot keeps the ticket amount.
        // Mutant M: '% 1' makes random always 0 => pays out and zeroes the pot.
        assertTrue(c.pot() == 10);
    }
}
